function BetterQoL.career_page.text(key)
  local e = BetterQoL.career_page.TX[key]
  if e == nil then
    return ""
  end
  local ok, s = pcall(funcLuaCommand, BetterQoL.career_page.C.TEXT_GET, e[1])
  if ok and type(s) == "string" and s ~= "" then
    return s
  end
  return e[2]
end

-- "{1}".."{4}" placeholders
function BetterQoL.career_page.fmt(key, ...)
  local s = BetterQoL.career_page.text(key)
  local args = {...}
  for i = 1, #args do
    s = string.gsub(s, "{" .. i .. "}", (string.gsub(tostring(args[i]), "%%", "%%%%")))
  end
  return s
end

-- year, month, day of a yyyymmdd number
function BetterQoL.career_page.ymd(v)
  return math.floor(v / 10000), math.floor(v / 100) % 100, v % 100
end

function BetterQoL.career_page.date(v, key)
  if type(v) ~= "number" or v <= 0 then
    return nil
  end
  local y, m, d = BetterQoL.career_page.ymd(v)
  local s = BetterQoL.career_page.text(key or "date")
  s = string.gsub(s, "{yy}", string.format("%02d", y % 100))
  s = string.gsub(s, "{y}", string.format("%04d", y))
  s = string.gsub(s, "{m}", string.format("%02d", m))
  s = string.gsub(s, "{d}", string.format("%02d", d))
  return s
end

function BetterQoL.career_page.exists(layer)
  return funcLuaMenuCommand(BetterQoL.career_page.C.EXIST_LAYER, layer) == true
end

function BetterQoL.career_page.is_open(layer, k)
  return funcLuaMenuCommand(BetterQoL.career_page.C.IS_OPEN_LAYER, layer, k) == true
end

function BetterQoL.career_page.ex(chara, group)
  if chara == nil or chara == 0 then
    return nil
  end
  local r = {pcall(funcLuaCommand, BetterQoL.career_page.CMD_EX, chara, group)}
  if r[1] ~= true or r[2] ~= true then
    return nil
  end
  local v = {}
  for i = 3, #r do
    v[#v + 1] = type(r[i]) == "number" and r[i] or 0
  end
  return v
end

function BetterQoL.career_page.open(L, k)
  if not BetterQoL.career_page.is_open(L, k) then
    funcLuaMenuCommand(BetterQoL.career_page.C.OPEN_LAYER, L, k)
  end
end


function BetterQoL.career_page.day_number(v)
  local y, m, d = BetterQoL.career_page.ymd(v)
  if m <= 2 then
    y = y - 1
  end
  local era = math.floor(y / 400)
  local yoe = y - era * 400
  local mp = (m + 9) % 12
  local doy = math.floor((153 * mp + 2) / 5) + d - 1
  local doe = yoe * 365 + math.floor(yoe / 4) - math.floor(yoe / 100) + doy
  return era * 146097 + doe
end

-- rough drawn width of a 22 px text (the timeline only keeps its dates apart with it)
function BetterQoL.career_page.width(s)
  local n = #(string.gsub(s, "[\128-\191]", ""))
  return n * BetterQoL.career_page.L.char_px
end

function BetterQoL.career_page.known(day)
  return type(day) == "number" and day > 0
end

-- Builds the timeline groups.
function BetterQoL.career_page.milestones(signed, before, first_goal, first_mvp, today)
  local items = {}
  local short = function(v)
    return BetterQoL.career_page.date(v, "date_short")
  end
  if BetterQoL.career_page.known(signed) then
    items[#items + 1] = {signed, BetterQoL.career_page.I_SIGNED, short(signed)}
  elseif BetterQoL.career_page.known(before) then
    items[#items + 1] = {before, BetterQoL.career_page.I_SIGNED, BetterQoL.career_page.fmt("before", short(before))}
  end
  if BetterQoL.career_page.known(first_goal) then
    items[#items + 1] = {first_goal, BetterQoL.career_page.I_GOAL, short(first_goal)}
  end
  if BetterQoL.career_page.known(first_mvp) then
    items[#items + 1] = {first_mvp, BetterQoL.career_page.I_MVP, short(first_mvp)}
  end
  table.sort(items, function(a, b)
    if a[1] ~= b[1] then
      return a[1] < b[1]
    end
    return a[2] < b[2]
  end)
  local groups = {}
  for _, it in ipairs(items) do
    local g = groups[#groups]
    if g ~= nil and g.day == it[1] then
      g.icons[#g.icons + 1] = it[2]
    else
      groups[#groups + 1] = {day = it[1], icons = {it[2]}, date = it[3]}
    end
  end
  if BetterQoL.career_page.known(today) and (#groups == 0 or groups[#groups].day < today) then
    groups[#groups + 1] = {day = today, icons = {BetterQoL.career_page.I_TODAY}, date = BetterQoL.career_page.date(today, "date_short"), today = true}
  end
  return groups
end

-- Returns the x centre of each group.
function BetterQoL.career_page.timeline_x(groups)
  local L = BetterQoL.career_page.L
  local n = #groups
  local xs, half = {}, {}
  if n == 0 then
    return xs
  end
  local d0 = BetterQoL.career_page.day_number(groups[1].day)
  local span = BetterQoL.career_page.day_number(groups[n].day) - d0
  for i, g in ipairs(groups) do
    local w = g.today and L.dot or (#g.icons * L.icon_pitch - (L.icon_pitch - L.icon))
    half[i] = math.max(w, BetterQoL.career_page.width(g.date or "")) / 2
    if span > 0 then
      xs[i] = L.first_x + (BetterQoL.career_page.day_number(g.day) - d0) / span * (L.last_x - L.first_x)
    else
      xs[i] = L.first_x
    end
  end
  xs[1] = math.max(xs[1], half[1] - L.half)       -- a wide first date stays inside the page
  for i = 2, n do
    xs[i] = math.max(xs[i], xs[i - 1] + half[i - 1] + half[i] + L.gap)
  end
  if n > 1 and xs[n] > L.last_x then
    xs[n] = L.last_x
    for i = n - 1, 1, -1 do
      xs[i] = math.min(xs[i], xs[i + 1] - half[i] - half[i + 1] - L.gap)
    end
  end
  return xs
end

-- Returns the table's rows.
function BetterQoL.career_page.mode_rows(chara, max)
  local rows = {}
  for m = 0, #BetterQoL.career_page.MODES do
    local v = BetterQoL.career_page.ex(chara, 10 + m)
    if v ~= nil and v[1] > 0 then
      rows[#rows + 1] = {BetterQoL.career_page.text(BetterQoL.career_page.MODES[m]), v[1], v[5], v[6], v[7] or 0, v[8] or 0, order = m}
    end
  end
  table.sort(rows, function(a, b)
    if a[2] ~= b[2] then
      return a[2] > b[2]
    end
    return a.order < b.order
  end)
  if #rows > max then
    local other = {BetterQoL.career_page.text("mode_other"), 0, 0, 0, 0, 0}
    for i = max, #rows do
      for c = 2, 6 do
        other[c] = other[c] + rows[i][c]
      end
    end
    for i = #rows, max, -1 do
      rows[i] = nil
    end
    rows[max] = other
  end
  return rows
end

-- Returns the centres of the number columns.
function BetterQoL.career_page.columns(keeper)
  local L = BetterQoL.career_page.L
  local n = keeper and 5 or 4
  local w = (L.half - L.num_x0) / n
  local xs = {}
  for i = 1, n do
    xs[i] = L.num_x0 + w * (i - 0.5)
  end
  return xs
end

-- how many mode rows fit a page of `height` px (at least 1, at most L.max_rows)
function BetterQoL.career_page.rows_fit(height)
  local L = BetterQoL.career_page.L
  local fixed = L.head_top + L.row_h + L.total_h + L.record_h
  return math.max(1, math.min(L.max_rows, math.floor((height - fixed) / L.row_h)))
end

function BetterQoL.career_page.build_plan(chara, height)
  local T, L = BetterQoL.career_page.text, BetterQoL.career_page.L
  local plan = {texts = {}, chips = {}, quads = {}, chara = chara, height = height}
  local nt, nb = 0, 0
  local function text(x, y, grey, blue)
    plan.texts[#plan.texts + 1] = {BetterQoL.career_page.TEXT, nt, x, y, grey or "", blue or ""}
    nt = nt + 1
  end
  local function big(x, y, blue)
    plan.texts[#plan.texts + 1] = {BetterQoL.career_page.TEXTB, nb, x, y, "", blue}
    nb = nb + 1
  end
  local function quad(L_, i, x0, y0, x1, y1)
    plan.quads[#plan.quads + 1] = {L_, i, x0, y0, x1, y1}
  end
  local v = BetterQoL.career_page.ex(chara, 0)
  if v == nil then
    text(0, L.head_top, T("no_data"), "")
    return plan
  end
  local x = BetterQoL.career_page.ex(chara, 2) or {0, 0, 1, 0, 0, 1, 0, 0}
  local signed, before, role = v[1], v[2], v[4]
  local m, w, d, l, g, a, mvp, saves, first_goal = v[5], v[6], v[7], v[8], v[9], v[10], v[11], v[14], v[20]
  local first_mvp, best_goals, best_goals_exact, best_goals_day = x[1], x[2], x[3], x[4]
  local best_saves, best_saves_exact, best_saves_day, today = x[5], x[6], x[7], x[8]
  local keeper = role == 1

  -- timeline
  local groups = BetterQoL.career_page.milestones(signed, before, first_goal, first_mvp, today)
  local xs = BetterQoL.career_page.timeline_x(groups)
  if #groups > 0 then
    local t = L.line_y
    if #xs > 1 then
      quad(BetterQoL.career_page.BAND, BetterQoL.career_page.Q_LINE, xs[1], t - 2, xs[#xs], t + 2)
    end
    for i, grp in ipairs(groups) do
      local n = #grp.icons
      for j, icon in ipairs(grp.icons) do
        local cx = xs[i] + (j - (n + 1) / 2) * L.icon_pitch
        local s = grp.today and L.dot or L.icon
        quad(BetterQoL.career_page.ICON, icon, cx - s / 2, t - s / 2, cx + s / 2, t + s / 2)
      end
      text(xs[i], L.date_y, grp.date or "", "")
    end
  end

  -- Builds the chips.
  local chips = {{T("col_matches"), tostring(m)}, {T("l_record"), BetterQoL.career_page.fmt("v_record", w, d, l)},
    {T("col_goals"), tostring(g)}}
  local right = L.half
  for i = #chips, 1, -1 do
    local cw = BetterQoL.career_page.CHIP_W[i]
    local cx = right - cw / 2
    plan.chips[#plan.chips + 1] = {i - 1, cx, L.chip_h / 2, chips[i][1], chips[i][2]}
    quad(BetterQoL.career_page.BAND, BetterQoL.career_page.Q_CHIP + i - 1, cx - cw / 2, 0, cx + cw / 2, L.chip_h)
    right = right - cw - L.chip_gap
  end

  -- Draws the card back.
  local cols = BetterQoL.career_page.columns(keeper)
  local y = L.head_top
  quad(BetterQoL.career_page.BAND, BetterQoL.career_page.Q_HEAD, -L.half, y, L.half, y + L.row_h)
  local pos = type(role) == "number" and role >= 1 and role <= 4 and T("pos" .. role) or nil
  local since = BetterQoL.career_page.date(signed) or BetterQoL.career_page.date(before)
  local head = pos or ""
  if pos and since then
    head = BetterQoL.career_page.fmt("header", pos, since)
  elseif since then
    head = since
  end
  text(L.name_x, y + L.row_h / 2, "", head)
  local titles = {T("col_matches"), T("col_goals"), T("col_assists"), T("l_mvp"), T("col_saves")}
  for i, cx in ipairs(cols) do
    text(cx, y + L.row_h / 2, titles[i], "")
  end
  y = y + L.row_h
  for _, r in ipairs(BetterQoL.career_page.mode_rows(chara, BetterQoL.career_page.rows_fit(height))) do
    local cy = y + L.row_h / 2
    text(L.name_x, cy, r[1], "")
    local nums = {r[2], r[3], r[4], r[5], r[6]}
    for i, cx in ipairs(cols) do
      text(cx, cy, "", tostring(nums[i]))
    end
    y = y + L.row_h
  end
  quad(BetterQoL.career_page.BAND, BetterQoL.career_page.Q_TOTAL, -L.half, y, L.half, y + L.total_h)
  local cy = y + L.total_h / 2
  big(L.name_x, cy, T("total"))
  local totals = {m, g, a, mvp, saves}
  for i, cx in ipairs(cols) do
    big(cx, cy, tostring(totals[i]))
  end
  y = y + L.total_h
  local record = nil
  if keeper and best_saves_exact == 1 and best_saves > 0 then
    record = BetterQoL.career_page.fmt("best_saves", best_saves, BetterQoL.career_page.date(best_saves_day) or T("none"))
  elseif best_goals_exact == 1 and best_goals > 0 then
    record = BetterQoL.career_page.fmt(best_goals == 1 and "best_goal_one" or "best_goals", best_goals,
      BetterQoL.career_page.date(best_goals_day) or T("none"))
  end
  if record then
    text(0, y + L.record_h / 2, record, "")
  end
  return plan
end

function BetterQoL.career_page.count(L)
  if L == BetterQoL.career_page.TEXT then
    return BetterQoL.career_page.TEXT_COUNT
  elseif L == BetterQoL.career_page.TEXTB then
    return BetterQoL.career_page.TEXTB_COUNT
  elseif L == BetterQoL.career_page.CELLT then
    return BetterQoL.career_page.ROW_CELLS[0]
  elseif L == BetterQoL.career_page.PANEL then
    return 1
  elseif BetterQoL.career_page.QUAD_TRACE[L] ~= nil then
    return #BetterQoL.career_page.QUAD_TRACE[L] + 1
  end
  local n = 0
  for r = 1, 4 do
    n = n + BetterQoL.career_page.ROW_CELLS[r]
  end
  return n
end

-- every layer of the page (the panel first)
function BetterQoL.career_page.layers()
  return {BetterQoL.career_page.PANEL, BetterQoL.career_page.CELL, BetterQoL.career_page.CELLT, BetterQoL.career_page.TEXT, BetterQoL.career_page.TEXTB, BetterQoL.career_page.BAND, BetterQoL.career_page.ICON}
end

function BetterQoL.career_page.hide_all(except)
  local C = BetterQoL.career_page.C
  for _, L in ipairs(BetterQoL.career_page.layers()) do
    if BetterQoL.career_page.exists(L) then
      for k = 0, BetterQoL.career_page.count(L) - 1 do
        if not (except and except[L] and except[L][k]) and BetterQoL.career_page.is_open(L, k) then
          funcLuaMenuCommand(C.LAYER_VISIBLE, L, k, false)
        end
      end
    end
  end
end

function BetterQoL.career_page.set_text(L, k, grey, blue)
  local C = BetterQoL.career_page.C
  funcLuaMenuCommand(C.TEXT, L, BetterQoL.career_page.N_LABEL, grey or "", k)
  funcLuaMenuCommand(C.TEXT, L, BetterQoL.career_page.N_VALUE, blue or "", k)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L, BetterQoL.career_page.N_LABEL, true, k)
  funcLuaMenuCommand(C.TEXT_VISIBLE, L, BetterQoL.career_page.N_VALUE, true, k)
end

-- the plan's layers opened and their texts set, everything hidden until Apply places it
function BetterQoL.career_page.prepare(plan)
  if not BetterQoL.career_page.exists(BetterQoL.career_page.PANEL) or not BetterQoL.career_page.exists(BetterQoL.career_page.TEXT) or not BetterQoL.career_page.exists(BetterQoL.career_page.TEXTB)
      or not BetterQoL.career_page.exists(BetterQoL.career_page.CELLT) then
    return false
  end
  BetterQoL.career_page.open(BetterQoL.career_page.PANEL, 0)
  local used = {}
  local function mark(L, k)
    used[L] = used[L] or {}
    used[L][k] = true
  end
  for _, t in ipairs(plan.texts) do
    BetterQoL.career_page.open(t[1], t[2])
    BetterQoL.career_page.set_text(t[1], t[2], t[5], t[6])
    mark(t[1], t[2])
  end
  for _, c in ipairs(plan.chips) do
    BetterQoL.career_page.open(BetterQoL.career_page.CELLT, c[1])
    BetterQoL.career_page.set_text(BetterQoL.career_page.CELLT, c[1], c[4], c[5])
    mark(BetterQoL.career_page.CELLT, c[1])
  end
  for _, q in ipairs(plan.quads) do
    mark(q[1], q[2])
  end
  mark(BetterQoL.career_page.PANEL, 0)
  plan.used = used
  BetterQoL.career_page.hide_all(nil)
  return true
end

function BetterQoL.career_page.quad(L, i, x0, y0, x1, y1, origin)
  local C = BetterQoL.career_page.C
  if not BetterQoL.career_page.exists(L) then
    return false
  end
  local key = L * 16 + i
  if not BetterQoL.career_page.is_open(L, i) then
    BetterQoL.career_page.quadReady[key] = nil
    funcLuaMenuCommand(C.OPEN_LAYER, L, i)
    return false
  end
  if funcLuaMenuCommand(C.LOADING, L) == true then
    return false
  end
  local ready = BetterQoL.career_page.quadReady[key]
  if ready == nil then
    pcall(funcLuaMenuCommand, C.TRACE, BetterQoL.career_page.L_STATUS, 0, BetterQoL.career_page.QUAD_TRACE[L][i], true)
    for _, m in ipairs(BetterQoL.career_page.BAND_HIDE) do
      funcLuaMenuCommand(C.MESH_VISIBLE, L, m, false, i)
    end
    funcLuaMenuCommand(C.SPRITE, L, BetterQoL.career_page.TX_OWN, BetterQoL.career_page.QUAD_SPRITE[L][i], BetterQoL.career_page.SP_FRAME, 0, i)
    ready = {}
    BetterQoL.career_page.quadReady[key] = ready
  end
  local f, o = BetterQoL.career_page.FRAME, origin
  local place = x0 .. "," .. y0 .. "," .. x1 .. "," .. y1 .. "," .. o[1] .. "," .. o[2]
  if ready.place ~= place then
    ready.place = place
    local sx, sy = (x1 - x0) / f[3], (y1 - y0) / f[4]
    funcLuaMenuCommand(C.SCALE, L, sx, sy, 1, i)
    funcLuaMenuCommand(C.POS, L, x0 - o[1] - f[1] * sx, o[2] - y0 + f[2] * sy, 0, i)
  end
  funcLuaMenuCommand(C.LAYER_VISIBLE, L, i, true)
  return true
end

-- Applies the plan placed on the screen with geo.
function BetterQoL.career_page.apply(geo)
  local plan = BetterQoL.career_page.plan
  if plan == nil or plan.used == nil then
    return
  end
  local C, o = BetterQoL.career_page.C, geo.origin
  local x0 = o[1] + BetterQoL.career_page.CELL_X0               -- default place of the free texts (the locator of cell (0, 0))
  BetterQoL.career_page.visible = true
  BetterQoL.career_page.strips(false)
  if BetterQoL.career_page.is_open(BetterQoL.career_page.PANEL, 0) then
    funcLuaMenuCommand(C.LAYER_VISIBLE, BetterQoL.career_page.PANEL, 0, true)
  end
  for _, t in ipairs(plan.texts) do
    if BetterQoL.career_page.is_open(t[1], t[2]) then
      funcLuaMenuCommand(C.POS, t[1], geo.center + t[3] - x0, o[2] - (geo.top + t[4]), 0, t[2])
      funcLuaMenuCommand(C.LAYER_VISIBLE, t[1], t[2], true)
    end
  end
  for _, c in ipairs(plan.chips) do
    local k = c[1]
    if BetterQoL.career_page.is_open(BetterQoL.career_page.CELLT, k) then
      local dx = geo.center + c[2] - (x0 + BetterQoL.career_page.CELL_DX * k)
      funcLuaMenuCommand(C.POS, BetterQoL.career_page.CELLT, dx, o[2] - (geo.top + c[3]), 0, k)
      funcLuaMenuCommand(C.LAYER_VISIBLE, BetterQoL.career_page.CELLT, k, true)
    end
  end
  for _, q in ipairs(plan.quads) do
    BetterQoL.career_page.quad(q[1], q[2], geo.center + q[3], geo.top + q[4], geo.center + q[5], geo.top + q[6], o)
  end
end

function BetterQoL.career_page.strips(on)
  if not BetterQoL.career_page.exists(BetterQoL.career_page.ROWS) then
    return
  end
  for k = 0, 4 do
    if BetterQoL.career_page.is_open(BetterQoL.career_page.ROWS, k) then
      funcLuaMenuCommand(BetterQoL.career_page.C.LAYER_VISIBLE, BetterQoL.career_page.ROWS, k, on)
    end
  end
end

function BetterQoL.career_page.show(chara)
  local geo = BetterQoL.career_page.if_plate() and BetterQoL.career_page.hostGeo or BetterQoL.career_page.GEO_RETAIL
  local plan = BetterQoL.career_page.build_plan(chara, geo and geo.height or BetterQoL.career_page.GEO_RETAIL.height)
  if not BetterQoL.career_page.prepare(plan) then
    BetterQoL.career_page.log("layers missing (betterqol_cs_panel / betterqol_cs_text / betterqol_cs_textb / betterqol_cs_cellt)")
    return
  end
  BetterQoL.career_page.plan = plan
  BetterQoL.career_page.shown = true
  BetterQoL.career_page.strips(false)
  if not BetterQoL.career_page.if_plate() then
    BetterQoL.career_page.apply(BetterQoL.career_page.GEO_RETAIL)
  end
  BetterQoL.career_page.log("show", chara or 0, #plan.texts, #plan.quads)
end

-- Show under pcall, an error logged
function BetterQoL.career_page.show_logged(ch)
  local ok, err = pcall(BetterQoL.career_page.show, ch)
  if not ok then
    BetterQoL.career_page.log("show error", tostring(err))
  end
end

function BetterQoL.career_page.hide()
  BetterQoL.career_page.shown = false
  BetterQoL.career_page.plan = nil
  BetterQoL.career_page.hide_all(nil)
end

function BetterQoL.career_page.mine(ptype)
  return ptype == BetterQoL.career_page.TYPE
end

function BetterQoL.career_page.if_plate()
  return type(CharacterReforged) == "table" and type(CharacterReforged.hyper_page_decor) == "function"
end

function BetterQoL.career_page.current()
  return GetNowPageIdx ~= nil and GetNowPageIdx() == BetterQoL.career_page.PAGE
end

-- Keeps every layer of the page hidden unless the mod's page is the current page.
function BetterQoL.career_page.guard(force)
  if GetNowPageIdx == nil or BetterQoL.career_page.current() then
    return
  end
  BetterQoL.career_page.shown = false
  if force or BetterQoL.career_page.visible then
    BetterQoL.career_page.visible = false
    BetterQoL.career_page.hide_all(nil)
  end
end

-- Runs every frame on the mod's page of the retail plate.
function BetterQoL.career_page.frame()
  if not BetterQoL.career_page.shown or BetterQoL.career_page.if_plate() or not BetterQoL.career_page.current() then
    return
  end
  BetterQoL.career_page.apply(BetterQoL.career_page.GEO_RETAIL)
end

-- a paged plate's frame step (the declaration's plate_step)
function BetterQoL.career_page.own_layout(on, geo)
  if type(geo) ~= "table" then
    return
  end
  BetterQoL.career_page.hostGeo = geo
  if not on or not BetterQoL.career_page.shown then
    return
  end
  local plan = BetterQoL.career_page.plan
  if plan ~= nil and plan.height ~= geo.height then
    BetterQoL.career_page.show(plan.chara)
  end
  BetterQoL.career_page.apply(geo)
end

function BetterQoL.career_page.decor(ptype)
  if not BetterQoL.career_page.exists(BetterQoL.career_page.L_STATUS) then
    return
  end
  local L, C = BetterQoL.career_page.L_STATUS, BetterQoL.career_page.C
  local mine = BetterQoL.career_page.mine(ptype)
  local ifp = BetterQoL.career_page.if_plate()
  funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_T_PARAM1, ptype == 1, 0)
  funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_T_PARAM2, ptype == 0, 0)
  funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_T_TEAMPASS, ptype == 2, 0)
  funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_DOT4_ON, ptype == 2, 0)
  if mine then
    funcLuaMenuCommand(C.SPRITE, L, BetterQoL.career_page.TX_TITLE, BetterQoL.career_page.SP_TITLE, BetterQoL.career_page.SP_SIXTH, 0, 0)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_SIXTH_TITLE, true, 0)
  elseif not ifp then
    funcLuaMenuCommand(C.SPRITE, L, BetterQoL.career_page.TX_S1105, BetterQoL.career_page.SP_SIXTH, BetterQoL.career_page.SP_SIXTH, 0, 0)
    funcLuaMenuCommand(C.MESH_VISIBLE, L, BetterQoL.career_page.M_SIXTH_TITLE, ptype == 3, 0)
  end
end

function BetterQoL.career_page.selected_chara(fallback)
  local ch = 0
  if GetPersonalPlateSelectCharaStHdlAuto ~= nil then
    local ok, v = pcall(GetPersonalPlateSelectCharaStHdlAuto)
    if ok and type(v) == "number" then
      ch = v
    end
  end
  if ch == 0 and type(fallback) == "number" then
    ch = fallback
  end
  return ch
end

function BetterQoL.career_page.decor_all(ptype)
  if BetterQoL.career_page.if_plate() then
    pcall(CharacterReforged.hyper_page_decor, ptype)
  else
    pcall(BetterQoL.career_page.decor, ptype)
  end
end

function BetterQoL.career_page.page_change(fname, orig, a1, a2, ...)
  if BetterQoL.career_page.mine(a2) then
    local r = orig(a1, 2, ...)
    BetterQoL.career_page.decor_all(a2)
    if fname == "ChangePersonalPlatePageByCharaParamId" then
      pcall(BetterQoL.career_page.show, 0)
      return r
    end
    local ch = BetterQoL.career_page.selected_chara(a1)
    if ch == 0 then
      pcall(BetterQoL.career_page.hide)                -- no player focused (empty slot): nothing of the page
      return r
    end
    BetterQoL.career_page.show_logged(ch)
    return r
  end
  local r = orig(a1, a2, ...)
  pcall(BetterQoL.career_page.hide)
  if not BetterQoL.career_page.if_plate() then
    pcall(BetterQoL.career_page.decor, a2)
  end
  return r
end

BetterQoL.career_page.wrap("hyper_page_decor", function(orig)
  return function(ptype, ...)
    local r = orig(ptype, ...)
    pcall(BetterQoL.career_page.decor, ptype)
    return r
  end
end, CharacterReforged)

for _, fname in ipairs({"OnSetupLayer", "OnOpenLayer", "OnOpenEndLayer"}) do
  VRFW.host.wrap_once(fname, "BetterQoL.career_page", function(orig, ...)
    local r = orig(...)
    pcall(BetterQoL.career_page.guard, true)
    return r
  end)
end

VRFW.host.wrap_once("PostStep", "BetterQoL.career_page", function(orig, ...)
  local r = orig(...)
  pcall(BetterQoL.career_page.guard)
  pcall(BetterQoL.career_page.frame)
  return r
end)

-- The page changes the page itself only while no plate owns the chain of declared pages.
-- The owner is read at each page change because the BetterQoL patch files run before the plate that sets it.
for _, fname in ipairs({"ChangePersonalPlatePageByCharaHdl", "ChangePersonalPlatePageByCharaParamId"}) do
  VRFW.host.wrap_once(fname, "BetterQoL.career_page", function(orig, a1, a2, ...)
    if VRFW.player_pages ~= nil and VRFW.player_pages.page_change_owner ~= nil then
      return orig(a1, a2, ...)
    end
    return BetterQoL.career_page.page_change(fname, orig, a1, a2, ...)
  end)
end

VRFW.host.wrap_once("UpdatePageInfo", "BetterQoL.career_page", function(orig, ...)
  local r = orig(...)
  if BetterQoL.career_page.current() then
    -- Handles an empty slot.
    local ch = BetterQoL.career_page.selected_chara(nil)
    if ch == 0 then
      pcall(BetterQoL.career_page.hide)
      return r
    end
    BetterQoL.career_page.show_logged(ch)
  end
  return r
end)

-- Handles the next and previous page.
